#[derive(Clone)]
struct KopfData<const CHANNELS: usize, const POLES: usize> {
    couplings: SMatrix<f64, CHANNELS, POLES>,
    background: SMatrix<f64, CHANNELS, CHANNELS>,
    channel_mass_1: SVector<f64, CHANNELS>,
    channel_mass_2: SVector<f64, CHANNELS>,
    pole_masses: SVector<f64, POLES>,
    l: L,
    adler: Option<(f64, f64)>,
}

impl<const CHANNELS: usize, const POLES: usize> KopfData<CHANNELS, POLES> {
    fn expression(self, s: Expr, production: [Expr; POLES]) -> KMatrixResult<Expr> {
        let pole_masses = vector(self.pole_masses.iter().copied());
        let channel_mass_1 = vector(self.channel_mass_1.iter().copied());
        let channel_mass_2 = vector(self.channel_mass_2.iter().copied());
        let couplings = matrix_from_flat(
            CHANNELS,
            POLES,
            (0..CHANNELS)
                .flat_map(|channel| (0..POLES).map(move |pole| self.couplings[(channel, pole)])),
        )?;
        let barriers = blatt_weisskopf_barriers(
            &s,
            channel_mass_1,
            channel_mass_2,
            &pole_masses,
            self.l,
            QR_DEFAULT,
        )?;

        let background = matrix_from_flat(
            CHANNELS,
            CHANNELS,
            (0..CHANNELS).flat_map(|i| {
                let barriers = barriers.clone();
                (0..CHANNELS).map(move |j| {
                    (0..POLES).fold(Expr::from(0.0), |sum, pole| {
                        sum + barriers.matrix_element(i, pole)
                            * self.background[(i, j)]
                            * barriers.matrix_element(j, pole)
                    })
                })
            }),
        )?;
        let mut k = k_matrix_with_background(&s, &pole_masses, &couplings, &barriers, background)?;
        if let Some((s_0, s_norm)) = self.adler {
            let adler = (&s - s_0) / s_norm;
            k = matrix_from_flat(
                CHANNELS,
                CHANNELS,
                (0..CHANNELS).flat_map(|row| {
                    let adler = adler.clone();
                    let k = k.clone();
                    (0..CHANNELS).map(move |col| &adler * k.matrix_element(row, col))
                }),
            )?;
        }
        let p = p_vector(&s, &pole_masses, vector(production), couplings, barriers)?;
        let mut phase_space_elements = Vec::with_capacity(CHANNELS * CHANNELS);
        for row in 0..CHANNELS {
            for col in 0..CHANNELS {
                phase_space_elements.push(if row == col {
                    chew_mandelstam(&s, self.channel_mass_1[row], self.channel_mass_2[row])
                } else {
                    Expr::from(0.0)
                });
            }
        }
        let phase_space = matrix_from_flat(CHANNELS, CHANNELS, phase_space_elements)?;
        f_vector(s, pole_masses, k, p, phase_space)
    }

    fn resampled<const PARAMETERS: usize>(
        mut self,
        covariance: SMatrix<f64, PARAMETERS, PARAMETERS>,
        seed: u64,
    ) -> Self {
        let mut mean = SVector::<f64, PARAMETERS>::zeros();
        let mut index = 0;
        for value in self.couplings.iter() {
            mean[index] = *value;
            index += 1;
        }
        for value in self.background.iter() {
            mean[index] = *value;
            index += 1;
        }
        for value in self.pole_masses.iter() {
            mean[index] = *value;
            index += 1;
        }
        if let Some((s_0, _)) = self.adler {
            mean[index] = s_0;
        }

        let sampled = sample_normal(mean, covariance, seed);
        let mut index = 0;
        self.couplings =
            SMatrix::from_iterator(sampled.iter().skip(index).take(CHANNELS * POLES).copied());
        index += CHANNELS * POLES;
        self.background = SMatrix::from_iterator(
            sampled
                .iter()
                .skip(index)
                .take(CHANNELS * CHANNELS)
                .copied(),
        );
        index += CHANNELS * CHANNELS;
        self.pole_masses = SVector::from_iterator(sampled.iter().skip(index).take(POLES).copied());
        index += POLES;
        if let Some((_, normalization)) = self.adler {
            self.adler = Some((sampled[index], normalization));
        }
        self
    }
}

fn sample_normal<const PARAMETERS: usize>(
    mean: SVector<f64, PARAMETERS>,
    covariance: SMatrix<f64, PARAMETERS, PARAMETERS>,
    seed: u64,
) -> SVector<f64, PARAMETERS> {
    let active = (0..PARAMETERS)
        .filter(|&row| covariance.row(row).iter().any(|&value| value != 0.0))
        .collect::<Vec<_>>();
    if active.is_empty() {
        return mean;
    }
    let active_mean = DVector::from_iterator(active.len(), active.iter().map(|&i| mean[i]));
    let active_covariance = DMatrix::from_fn(active.len(), active.len(), |row, col| {
        covariance[(active[row], active[col])]
    });
    let cholesky = Cholesky::new(active_covariance)
        .expect("active Kopf covariance matrix must be positive definite");
    let mut rng = Rng::with_seed(seed);
    let normal = DVector::from_iterator(
        active.len(),
        (0..active.len()).map(|_| rng.f64_normal(0.0, 1.0)),
    );
    let sampled_active = active_mean + cholesky.l() * normal;
    let mut sampled = mean;
    for (source, &target) in active.iter().enumerate() {
        sampled[target] = sampled_active[source];
    }
    sampled
}

macro_rules! channel_enum {
    ($name:ident { $($variant:ident => $index:expr),+ $(,)? }) => {
        #[doc = concat!("Channel selector for the `", stringify!($name), "` parameterization.")]
        #[derive(Copy, Clone, Debug, PartialEq, Eq, Hash)]
        pub enum $name {
            $(
                #[doc = concat!("Selects the `", stringify!($variant), "` channel.")]
                $variant
            ),+
        }

        impl $name {
            /// Returns the zero-based channel index.
            pub const fn index(self) -> usize {
                match self {
                    $(Self::$variant => $index),+
                }
            }
        }

        impl ComponentIndex for $name {
            fn component_index(self) -> usize {
                self.index()
            }
        }

        impl From<$name> for usize {
            fn from(channel: $name) -> Self {
                channel.index()
            }
        }
    };
}

