            std::array::from_fn(|pole| {
                complex(
                    Parameter::free(format!("{family}_beta_{pole}_re"))
                        .with_initial(0.1 + 0.2 * pole as f64),
                    Parameter::free(format!("{family}_beta_{pole}_im"))
                        .with_initial(0.2 + 0.2 * pole as f64),
                )
            })
