    #[test]
    fn covariance_resampling_is_deterministic_for_every_supported_family() {
        let production_5 = [
            Complex64::new(0.1, 0.2),
            Complex64::new(0.3, 0.4),
            Complex64::new(0.5, 0.6),
            Complex64::new(0.7, 0.8),
            Complex64::new(0.9, 1.0),
        ];
        let production_4 = production_5[..4].try_into().unwrap();
        let production_2 = production_5[..2].try_into().unwrap();
        let pairs = [
            (
                kopf_f0_resampled(S_KSKS, production_5, 7)
                    .unwrap()
                    .component(KopfF0Channel::PiPi),
                kopf_f0_resampled(S_KSKS, production_5, 7)
                    .unwrap()
                    .component(KopfF0Channel::PiPi),
            ),
            (
                kopf_f2_resampled(S_KSKS, production_4, 7)
                    .unwrap()
                    .component(KopfF2Channel::PiPi),
                kopf_f2_resampled(S_KSKS, production_4, 7)
                    .unwrap()
                    .component(KopfF2Channel::PiPi),
            ),
            (
                kopf_a0_resampled(S_KSKS, production_2, 7)
                    .unwrap()
                    .component(KopfA0Channel::PiEta),
                kopf_a0_resampled(S_KSKS, production_2, 7)
                    .unwrap()
                    .component(KopfA0Channel::PiEta),
            ),
            (
                kopf_a2_resampled(S_KSKS, production_2, 7)
                    .unwrap()
                    .component(KopfA2Channel::PiEta),
                kopf_a2_resampled(S_KSKS, production_2, 7)
                    .unwrap()
                    .component(KopfA2Channel::PiEta),
            ),
        ];
        for (lhs, rhs) in pairs {
            assert_eq!(lhs.to_graph().nodes(), rhs.to_graph().nodes());
        }
    }
